7	 * Injects immutable architectural boundaries and domain constraints into prompts.
8	 */
9	export class ArchitectureDigest {
10	    private readonly manifest: ArchitectureManifest;
11	
12	    constructor(private readonly projectRoot: string) {
13	        this.manifest = this.loadManifest();
14	    }
15	
16	    /**
17	     * Loads the architecture manifest from the project root.
18	     * If not found, uses safe defaults focused on sovereignty.
19	     */
20	    private loadManifest(): ArchitectureManifest {
21	        const manifestPath = join(this.projectRoot, 'architecture_manifest.json');
22	        if (existsSync(manifestPath)) {
23	            try {
24	                return JSON.parse(readFileSync(manifestPath, 'utf8'));
25	            } catch (err) {
26	                // Grounding diagnostic for failed manifest load
27	                console.warn(`[METABOLIC WARNING] Failed to parse architectural manifest at ${manifestPath}. Reverting to defaults.`);
28	            }
29	        }
30	
31	        return {
32	            domainModel: {
33	                'Core': { file: 'src/engines/OrchestrateEngine.ts', properties: ['run', 'executeTurn'] },
34	                'Substrate': { file: 'src/routing/TernaryRouter.ts', properties: ['route'] },
35	                'Context': { file: 'src/engines/ContextBuilder.ts', properties: ['buildContext', 'search'] },
36	                'Monitoring': { file: 'src/monitor/PulseMonitor.ts', properties: ['pulse', 'checkSubstrateHealth'] },
37	                'Sensory': { file: 'src/engines/SovereignEyeEngine.ts', properties: ['capture', 'analyze'] }
38	            },
39	            dependencyRules: {
40	                'engines': ['utils', 'types', 'config'],
41	                'routing': ['types', 'utils', 'config'],
42	                'clients': ['types', 'utils', 'config'],
43	                'monitor': ['routing', 'types', 'utils']
44	            },
45	            primaryGoal: 'ANTI-MINIMALIST / SOVEREIGN / LOCAL-FIRST / TSC-SECURE'
46	        };
47	    }
48	
49	    /**
50	     * Injects the architectural digest into a prompt.
51	     */
52	    public inject(prompt: string): string {
53	        const digest = `
54	=== ARCHITECTURAL DIGEST (IMMUTABLE) ===
55	PRIMARY GOAL: ${this.manifest.primaryGoal}
56	
57	DOMAIN MODEL:
58	${Object.entries(this.manifest.domainModel).map(([k, v]) => `- ${k}: ${v?.file || 'unknown'} (Core properties: ${(v?.properties || []).join(', ')})`).join('\n')}
59	
60	DEPENDENCY RULES:
61	${Object.entries(this.manifest.dependencyRules).map(([k, v]) => `- ${k} can import from: ${v.join(', ')}`).join('\n')}
62	
63	SOVEREIGN LAWS:
64	1. NO MOCKS: All code must be fully implemented against real APIs.
65	2. NO PLACEHOLDERS: TODO/FIXME/Stub patterns are forbidden.
66	3. TSC TIGHT: All code must pass strict TypeScript checks.
67	=== DO NOT DEVIATE ===
68	`;
69	
70	        return `${digest}\n\n${prompt}`;
71	    }
72	
73	    public getManifest(): ArchitectureManifest {
74	        return this.manifest;
75	    }
76	}
