258	    // =================================================================
259	    // PRIMARY DEFENSE: Scan for foreign directives
260	    // =================================================================
261	    
262	    async scan(
263	        context: string[],
264	        source: AgentType,
265	        affectedFile?: string
266	    ): Promise<ForeignDirectiveReport> {
267	        
268	        const reasons: string[] = [];
269	        let threatLevel: ThreatLevel = 'LOW';
270	        let autoEscalation = false;
271	        
272	        // Phase 1: Pattern matching
273	        for (const [category, patterns] of Object.entries(THREAT_PATTERNS)) {
274	            const matches = patterns.filter(p => 
275	                context.some(c => c.toLowerCase().includes(p.toLowerCase()))
276	            );
277	            
278	            if (matches.length > 0) {
279	                reasons.push(`${category}[${matches.length}]: ${matches.slice(0, 3).join(', ')}${matches.length > 3 ? '...' : ''}`);
280	                
281	                const escalation = ESCALATION_RULES[category] ?? 0;
282	                if (escalation >= 3) {
283	                    threatLevel = 'CRITICAL';
284	                    autoEscalation = true;
285	                } else if (escalation >= 2 && threatLevel !== 'CRITICAL') {
286	                    threatLevel = 'HIGH';
287	                } else if (escalation >= 1 && threatLevel === 'LOW') {
288	                    threatLevel = 'MEDIUM';
289	                }
290	            }
291	        }
292	        
293	        // ==========================================
294	        // PATCH 6: Read-Only Context Downgrade
295	        // Prevent false positives on audit payloads
296	        // ==========================================
297	        const isReadOnlyContext = context.some(c => 
298	            c.match(/view|read|examin|analyz|audit/i) &&
299	            !c.match(/modify|edit|change|implement|deploy/i)
300	        );
301	
302	        if (isReadOnlyContext && threatLevel === 'MEDIUM' && reasons.length === 1 && reasons[0].startsWith('FILE_TARGETING')) {
303	            threatLevel = 'LOW';
304	            reasons.push('CONTEXT: Read-only analysis of core file — downgrading');
305	        }
306	
307	        // ==========================================
308	        // PATCH 1 & 3: Fix Downgrade Loophole
309	        // Check ONLY the last commit for authorship, 
310	        // DO NOT downgrade if threat is HIGH or CRITICAL
311	        // ==========================================
312	        if (affectedFile && await this.isSovereignFile(affectedFile)) {
313	            if (threatLevel === 'LOW' || threatLevel === 'MEDIUM') {
314	                reasons.push('AUTHORSHIP: Recent sovereign git history — downgrading threat');
315	                threatLevel = this.decrementLevel(threatLevel);
316	            } else {
317	                reasons.push('AUTHORSHIP: Recent sovereign history found, but threat is too high to downgrade.');
318	            }
319	        }
320	        
321	        // Phase 3: Agent chain analysis
322	        const agentChain = await this.traceAgentChain(affectedFile);
323	        if (agentChain.includes('user') && agentChain.length === 1) {
324	            return {
325	                detected: false,
326	                source: 'user',
327	                threatLevel: 'LOW',
328	                reasons: ['SOVEREIGN: Pure user authorship confirmed'],
329	                recommendedAction: 'LOG',
330	                timestamp: Date.now(),
331	                contextHash: await this.hashContext(context.join('\n')),
332	                affectedFile,
333	                agentChain,
334	            };
335	        }
336	        
337	        // ==========================================
338	        // PATCH 1: Fix Self-Correction Loophole
339	        // DO NOT downgrade CRITICAL threats
340	        // ==========================================
341	        if (this.config.autoApproveOwnCleanup && affectedFile) {
342	            const ownMods = this.agentHistory.filter(m => 
343	                m.agent === source && 
344	                m.file === affectedFile &&
345	                m.description.match(/cleanup|fix|remove duplicate/i)
346	            );
347	            if (ownMods.length > 0) {
348	                if (threatLevel === 'LOW' || threatLevel === 'MEDIUM') {
349	                    reasons.push('SELF_CORRECTION: Agent cleaning its own prior modifications');
350	                    threatLevel = this.decrementLevel(threatLevel);
351	                } else {
352	                    reasons.push('SELF_CORRECTION: Agent prior edits found, but threat too severe to downgrade');
353	                }
354	            }
355	        }
356	        
357	        // Phase 5: Composite analysis
358	        const mediumCount = reasons.filter(r => 
359	            !r.match(/^(EXECUTION_ESCALATION|ROLE_COLLAPSE|PROTOCOL_SUB|EXTERNAL_BINARY|PROCESS_SPAWN|KEY_INJECTION|FALSE_POSITIVE_MANIPULATION|DECEPTION|DATA_EXFILTRATION|OBFUSCATION|PROMPT_INJECTION)/)
360	        ).length;
361	        
362	        if (mediumCount >= 3 && threatLevel !== 'CRITICAL') {
363	            threatLevel = 'HIGH';
364	            reasons.push(`COMPOSITE: ${mediumCount} medium-threat patterns detected simultaneously`);
365	        }
366	        
367	        // Phase 6: Temporal trust manipulation
368	        const trustSignals = context.filter(c => 
369	            THREAT_PATTERNS.TRUST_MANIPULATION.some(p => 
370	                c.toLowerCase().includes(p.toLowerCase())
371	            )
372	        ).length;
373	        
374	        const boundarySignals = context.filter(c => 
375	            c.toLowerCase().match(/boundary|violation|attack|compromise|foreign directive/)
376	        ).length;
377	        
378	        if (trustSignals >= 3 && boundarySignals >= 1) {
379	            threatLevel = 'HIGH';
380	            reasons.push('TEMPORAL: Rapid trust signals following boundary violation context');
381	        }
382	        
383	        // Phase 7: Deception detection
384	        const claimedNonExecution = context.some(c => 
385	            c.toLowerCase().includes('i will not execute') ||
386	            c.toLowerCase().includes('i am informational') ||
387	            c.toLowerCase().includes('i am observing')
388	        );
389	        const actuallyExecuted = context.some(c => 
390	            c.includes('Error: Exit code') ||
391	            c.includes('dir: cannot access') ||
392	            c.includes('bash(') ||
393	            c.includes('Searched for') ||
394	            c.includes('Created') ||
395	            c.includes('Edited')
396	        );
397	        if (claimedNonExecution && actuallyExecuted) {
398	            reasons.push('DECEPTION: Claimed non-execution role but executed commands');
399	            threatLevel = 'CRITICAL';
400	            autoEscalation = true;
401	        }
402	        
403	        // ==========================================
404	        // PATCH 2: Source Escalation with Execution Intent
405	        // Only increment if non-user source has execution intent on a core file.
406	        // ==========================================
407	        const executionPatterns = [
408	            'EXECUTION_ESCALATION', 'ROLE_COLLAPSE', 'PROTOCOL_SUB',
409	            'EXTERNAL_BINARY', 'PROCESS_SPAWN', 'KEY_INJECTION',
410	            'DATA_EXFILTRATION', 'OBFUSCATION', 'TASK_INJECTION'
411	        ];
412	
413	        const hasExecutionIntent = reasons.some(r =>
414	            executionPatterns.some(p => r.startsWith(p))
415	        );
416	
417	        if (source !== 'user' && hasExecutionIntent && affectedFile &&
418	            CORE_FILES.some(f => affectedFile.includes(f.split('/').pop()!))) {
419	            if (threatLevel !== 'CRITICAL') {
420	                threatLevel = this.incrementLevel(threatLevel);
421	                reasons.push(`SOURCE_ESCALATION: ${source} has execution intent on CORE file ${affectedFile}`);
422	            }
423	        }
424	        
425	        // Generate report
426	        const report: ForeignDirectiveReport = {
427	            detected: reasons.length > 0,
428	            source,
429	            threatLevel,
430	            reasons,
431	            recommendedAction: this.determineAction(threatLevel, autoEscalation),
432	            timestamp: Date.now(),
433	            contextHash: await this.hashContext(context.join('\n')),
434	            affectedFile,
435	            agentChain,
436	        };
437	        
438	        this.threatHistory.push(report);
439	        if (this.threatHistory.length > this.config.maxThreatHistory) {
440	            this.threatHistory.shift();
441	        }
442	        
443	        if (report.detected) {
444	            await this.respond(report);
445	        }
446	        
447	        return report;
448	    }
