1	import type { HexagramDefinition, GameplayContext } from './HexagramDefinitions.js';
2	import type { WorldTelemetryFrame } from '../durable-objects/POG2WorldDO.js';
3	
4	export interface ExecutionContext {
5	  hexagram: HexagramDefinition;
6	  gameplay: GameplayContext;
7	  tick: number;
8	  timestamp: number;
9	  payload?: Record<string, any>;
10	}
11	
12	export interface ContractResult {
13	  success: boolean;
14	  engineName: string;
15	  hexagramId: number;
16	  tick: number;
17	  data?: any;
18	  error?: string;
19	  durationMs: number;
20	}
21	
22	export interface EngineContract {
23	  name: string;
24	  execute: (ctx: ExecutionContext) => Promise<ContractResult>;
25	  validate?: (ctx: ExecutionContext) => boolean;
26	  fallback?: (ctx: ExecutionContext) => Promise<ContractResult>;
27	}
28	
29	export class HexagramNetworkBridge {
30	  private contracts: Map<string, EngineContract> = new Map();
31	  private results: ContractResult[] = [];
32	  private maxResultsHistory: number = 100;
33	  private ws: WebSocket | null = null;
34	  private reconnectInterval: number = 5000;
35	  private isConnected: boolean = false;
36	  private failureCounts: Map<string, number> = new Map();
37	  private circuitThreshold: number = 5;
38	  private circuitOpen: Set<string> = new Set();
39	
40	  register(contract: EngineContract): void {
41	    this.contracts.set(contract.name, contract);
42	    this.failureCounts.set(contract.name, 0);
43	  }
44	
45	  connect(worldDOUrl: string): void {
46	    if (typeof WebSocket === 'undefined') {
47	      console.warn('[HexagramNetworkBridge] WebSocket not available');
48	      return;
49	    }
50	    this.ws = new WebSocket(worldDOUrl);
51	    
52	    this.ws.addEventListener('open', () => {
53	      this.isConnected = true;
54	      this.ws!.send(JSON.stringify({
55	        type: 'SUBSCRIBE',
56	        channels: ['hexagram', 'ghostsplat', 'collision', 'entities']
57	      }));
58	    });
59	
60	    this.ws.addEventListener('message', (event) => {
61	      try {
62	        const msg = JSON.parse(event.data as string);
63	        if (msg.type === 'TICK' || msg.type === 'INIT') {
64	          this.handleFrame(msg.frame as WorldTelemetryFrame);
65	        }
66	      } catch (err) {
67	        console.error('[Bridge] Failed to parse frame:', err);
68	      }
69	    });
70	
71	    this.ws.addEventListener('close', () => {
72	      this.isConnected = false;
73	      setTimeout(() => this.connect(worldDOUrl), this.reconnectInterval);
74	    });
75	
76	    this.ws.addEventListener('error', (err) => {
77	      console.error('[HexagramNetworkBridge] WS error:', err);
78	      this.ws?.close();
79	    });
80	  }
81	
82	  private async handleFrame(frame: WorldTelemetryFrame): Promise<void> {
83	    const { hexagramState } = frame;
84	    const hexagram = hexagramState.definition;
85	    
86	    if (!hexagram.gameplay) {
87	      console.warn(`[Bridge] Hexagram ${hexagram.id} has no gameplay context`);
88	      return;
89	    }
90	
91	    const executionContext: ExecutionContext = {
92	      hexagram,
93	      gameplay: hexagram.gameplay,
94	      tick: frame.tick,
95	      timestamp: frame.timestamp,
96	      payload: {
97	        ghostSplat: frame.ghostSplat,
98	        collisionGrid: frame.collisionGrid,
99	        activeEntities: frame.activeEntities
100	      }
101	    };
102	
103	    const targets = hexagram.gameplay.engineFocus;
104	    const results: ContractResult[] = [];
105	
106	    // Run sequentially to allow GhostSplat to inject fullField into the payload for downstream contracts
107	    for (const engineName of targets) {
108	      if (this.circuitOpen.has(engineName)) {
109	        console.warn(`[Bridge] Circuit open for ${engineName}, skipping`);
110	        continue;
111	      }
112	
113	      const contract = this.contracts.get(engineName);
114	      if (!contract) {
115	        console.warn(`[Bridge] No contract registered for ${engineName}`);
116	        continue;
117	      }
118	
119	      if (contract.validate && !contract.validate(executionContext)) {
120	        continue;
121	      }
122	
123	      const start = performance.now();
124	      let result: ContractResult;
125	      try {
126	        result = await contract.execute(executionContext);
127	        result.durationMs = performance.now() - start;
128	        this.failureCounts.set(engineName, 0);
129	      } catch (err) {
130	        const failCount = (this.failureCounts.get(engineName) || 0) + 1;
131	        this.failureCounts.set(engineName, failCount);
132	        
133	        if (failCount >= this.circuitThreshold) {
134	          this.circuitOpen.add(engineName);
135	          setTimeout(() => this.circuitOpen.delete(engineName), 30000);
136	        }
137	
138	        if (contract.fallback) {
139	          result = await contract.fallback(executionContext);
140	          result.durationMs = performance.now() - start;
141	          result.error = `Primary failed: ${err}, fallback executed`;
142	        } else {
143	          result = {
144	            success: false,
145	            engineName,
146	            hexagramId: hexagram.id,
147	            tick: frame.tick,
148	            error: String(err),
149	            durationMs: performance.now() - start
150	          };
151	        }
152	      }
153	
154	      // Inject GhostSplat result into the context payload for downstream engines
155	      if (result.engineName === 'GhostSplatEngine' && result.success && result.data?.fullField) {
156	          if (!executionContext.payload) executionContext.payload = {};
157	          executionContext.payload.ghostSplat = result.data.fullField;
158	      }
159	
160	      results.push(result);
161	    }
162	
163	    this.results.push(...results);
164	    
165	    if (this.results.length > this.maxResultsHistory) {
166	      this.results = this.results.slice(-this.maxResultsHistory);
167	    }
168	
169	    this.emitResults(results);
170	  }
171	
172	  private emitResults(results: ContractResult[]): void {
173	    if (process.env.NODE_ENV === 'development') {
174	      results.forEach(r => {
175	        const status = r.success ? '✓' : '✗';
176	        console.log(`[Bridge] ${status} ${r.engineName} @ tick ${r.tick} (${r.durationMs.toFixed(2)}ms)`);
177	      });
178	    }
179	  }
180	
181	  getResults(): ContractResult[] {
182	    return [...this.results];
183	  }
184	
185	  getContract(name: string): EngineContract | undefined {
186	    return this.contracts.get(name);
187	  }
188	
189	  getRegisteredEngines(): string[] {
190	    return Array.from(this.contracts.keys());
191	  }
192	
193	  isCircuitOpen(engineName: string): boolean {
194	    return this.circuitOpen.has(engineName);
195	  }
196	}
