35	type SharedEncoderState = {
36		isWrite: boolean,
37		stack: object[],
38		hiddenstack: object[],
39		scan: number,
40		endoffset: number,
41		buffer: Buffer,
42		args: Record<string, unknown>
43	}
44	
45	export type DecodeState = SharedEncoderState & { isWrite: false };
46	export type EncodeState = SharedEncoderState & { isWrite: true };
47	
48	export type ResolvedReference = {
49		stackdepth: number,
50		resolve(v: unknown, oldvalue: number): number
51	}
52	
53	export type ChunkParser = {
54		read(state: DecodeState): any,
55		write(state: EncodeState, v: unknown): void,
56		getTypescriptType(indent: string): string,
57		getJsonSchema(): any,
58		readConst?(state: SharedEncoderState): any
59	}
60	
61	let parserFunctions: any;
62	let parserPrimitives: any;
63	let hardcodes: any;
64	
65	type ChunkParentCallback = (prop: string, childresolve: ResolvedReference) => ResolvedReference;
66	
67	function resolveAlias(typename: string, parent: ChunkParentCallback, typedef: TypeDef) {
68		if (!Object.hasOwn(typedef, typename)) {
69			throw new Error(`Type '${typename}' not found in typedef.json`);
70		}
71		const newtype = typedef[typename];
72		if (typeof newtype != "string") {
73			//TODO this recursion is unchecked
74			return buildParser(parent, newtype, typedef);
75		} else if (Object.hasOwn(parserPrimitives, newtype)) {
76			return parserPrimitives[newtype];
77		} else {
78			return resolveAlias(newtype, parent, typedef);
79		}
80	}
81	
82	export function buildParser(parent: ChunkParentCallback | null, chunkdef: unknown, typedef: TypeDef): ChunkParser {
83		parent ??= () => { throw new Error("reference failed to resolve"); };
84		switch (typeof chunkdef) {
85			case "boolean":
86			case "number":
87				return literalValueParser(chunkdef);
88			case "string": {
89				if (Object.hasOwn(parserPrimitives, chunkdef)) {
90					return parserPrimitives[chunkdef];
91				} else {
92					return resolveAlias(chunkdef, parent, typedef);
93				}
94			}
95			case "object":
96				if (chunkdef == null) {
97					return literalValueParser(null);
98				} else if (!Array.isArray(chunkdef)) {
99					return opcodesParser(chunkdef, parent, typedef);
100				} else {
101					if (chunkdef.length < 1) throw new Error(`'read' variables must either be a valid type-defining string, an array of type-defining strings / objects, or a valid type-defining object: ${JSON.stringify(chunkdef)}`);
102					const args = chunkdef.slice(1);
103					if (parserFunctions[chunkdef[0]]) {
104						return parserFunctions[chunkdef[0]](args, parent, typedef);
105					}
106				}
107			default:
108				throw new Error(`'read' variables must either be a valid type-defining string, an array of type-defining strings / objects, or a valid type-defining object: ${JSON.stringify(chunkdef)}`);
109		}
110	}
111	
112	function opcodesParser(chunkdef: {}, parent: ChunkParentCallback, typedef: TypeDef) {
113		const r: ChunkParser = {
114			read(state) {
115				const r: Record<string, any> = {};
116				const hidden: any = { $opcode: 0 };
117				state.stack.push(r);
118				state.hiddenstack.push(hidden);
119				if (debugdata && !debugdata.rootstate) { debugdata.rootstate = r; }
120				while (true) {
121					if (state.scan == state.endoffset) {
122						if (!hasexplicitnull) {
123							// throw new Error("ended reading opcode struct at end of file without 0x00 opcode");
124							console.log("ended reading opcode struct at end of file without 0x00 opcode");
125						}
126						break;
127					}
128					const opt = opcodetype.read(state);
129					hidden.$opcode = opt;
130					if (!hasexplicitnull && opt == 0) { break; }
131					const parser = map.get(opt);
132					if (debugdata) {
133						debugdata.opcodes.push({ op: (parser ? parser.key as string : `_0x${opt.toString(16)}_`), index: state.scan - 1, stacksize: state.stack.length });
134					}
135					if (!parser) { throw new Error("unknown chunk 0x" + opt.toString(16).toUpperCase()); }
136					(r as any)[parser.key] = parser.parser.read(state);
137				}
138				state.stack.pop();
139				state.hiddenstack.pop();
140				return r;
141			},
142			write(state: EncodeState, value: any) {
143				if (typeof value != "object" || !value) { throw new Error("oject expected") }
144				state.stack.push(value);
145				state.hiddenstack.push({});
146				for (const key in value) {
147					if (key.startsWith("$")) { continue; }
148					const opt = (opts as any)[key];
149					if (!opt) { throw new Error("unknown property " + key); }
150					opcodetype.write(state, opt.op);
151					opt.parser.write(state, value[key]);
152				}
153				if (!hasexplicitnull) {
154					opcodetype.write(state, 0);
155				}
156				state.stack.pop();
157				state.hiddenstack.pop();
158			},
159			getTypescriptType(indent) {
160				let r = "{\n";
161				const newindent = indent + "\t";
162				for (const val of map.values()) {
163					r += newindent + (val.key as string) + "?: " + val.parser.getTypescriptType(newindent) + " | null\n";
164				}
165				r += indent + "}";
166				return r;
167			},
168			getJsonSchema() {
169				return {
170					type: "object",
171					properties: Object.fromEntries([...map.values()]
172						.filter(prop => !(prop.key as string).startsWith("$"))
173						.map((prop) => {
174							return [prop.key, { oneOf: [prop.parser.getJsonSchema(), { type: "null" }] }];
175						})
176					)
177				}
178			}
179		}
180	
181		const resolveReference = function (targetprop: string, name: string, childresolve: ResolvedReference) {
182			const result: ResolvedReference = {
183				stackdepth: childresolve.stackdepth + 1,
184				resolve(v, oldvalue) {
185					if (typeof v != "object" || !v) { throw new Error("object expected"); }
186					const res = (v as any)[targetprop!];
187					return childresolve.resolve(res, oldvalue);
