1293				else { s.buffer.writeInt16BE(v | 0x8000, s.scan); s.scan += 2; }
1294			},
1295			min: -(2 ** 14), max: 2 ** 14 - 1
1296		},
1297		varuint: {
1298			read(s) {
1299				checkBounds(s, 2);
1300				const firstWord = s.buffer.readUInt16BE(s.scan);
1301				s.scan += 2;
1302				if ((firstWord & 0x8000) == 0) { return firstWord; }
1303				else { checkBounds(s, 2); const secondWord = s.buffer.readUInt16BE(s.scan); s.scan += 2; return ((firstWord & 0x7fff) << 16) | secondWord; }
1304			},
1305			write(s, v) {
1306				if (v < 0x8000) { s.buffer.writeUInt16BE(v, s.scan); s.scan += 2; }
1307				else { s.buffer.writeUint32BE((v | 0x80000000) >>> 0, s.scan); s.scan += 4; }
1308			},
1309			min: 0, max: 2 ** 31 - 1
1310		},
1311		varnullint: {
1312			read(s) {
