1	export interface ProgressionGate {
2	  name: string;
3	  minCombatLevel: number;
4	  requiredQuests: string[];
5	  requiredItems: number[]; // Item IDs
6	  requiredSkills: Record<string, number>; // skill → level
7	  location: { x: number; y: number; plane: number };
8	}
9	
10	export const ZUK_GATE: ProgressionGate = {
11	  name: 'TzKal-Zuk',
12	  minCombatLevel: 126,
13	  requiredQuests: ['the_brink_of_extinction', 'the_elder_kiln'],
14	  requiredItems: [49444], // Igneous stone or equivalent
15	  requiredSkills: { prayer: 95, herblore: 96, constitution: 99 },
16	  location: { x: 3200, y: 3200, plane: 0 } // Zuk arena
17	};
18	
19	export class ProgressionValidator {
20	  static canEnter(gate: ProgressionGate, state: any): boolean {
21	    if (!state) return false;
22	
23	    // 1. Combat Level check
24	    const combatLevel = this.calculateCombatLevel(state.skills ?? {});
25	    if (combatLevel < gate.minCombatLevel) return false;
26	    
27	    // 2. Quest stage check
28	    const quests = state.questStages ?? state.quests?.quests ?? state.quests ?? {};
29	    for (const quest of gate.requiredQuests) {
30	      const stage = quests[quest];
31	      const stageNum = typeof stage === 'object' ? (stage.stage ?? stage.status ?? 0) : (stage ?? 0);
32	      if (stageNum < 100) return false;
33	    }
34	    
35	    // 3. Item check (Inventory + Bank)
36	    const inventory = Array.isArray(state.inventory) ? state.inventory : [];
37	    const bank = Array.isArray(state.bank) ? state.bank : [];
38	    const inventoryAndBank = [...inventory, ...bank];
39	    
40	    for (const itemId of gate.requiredItems) {
41	      if (!inventoryAndBank.some((i: any) => {
42	        const id = typeof i === 'object' ? i.id : i;
43	        return id === itemId;
44	      })) return false;
45	    }
46	    
47	    // 4. Skill requirements
48	    for (const [skill, minLevel] of Object.entries(gate.requiredSkills)) {
49	      if (this.getSkillLevel(state.skills, skill, 1) < minLevel) return false;
50	    }
51	    
52	    return true;
53	  }
54	
55	  private static getSkillLevel(skills: any, skillName: string, defaultValue: number): number {
56	    if (!skills) return defaultValue;
57	    
58	    const skillIds: Record<string, number> = {
59	      attack: 1,
60	      strength: 2,
61	      defence: 5,
62	      ranged: 3,
63	      magic: 4,
64	      prayer: 7,
65	      constitution: 6,
66	      herblore: 9
67	    };
68	    
69	    const id = skillIds[skillName];
70	    
71	    // Check by string key first (e.g. skills.attack)
72	    let val = skills[skillName];
73	    if (val !== undefined) {
74	      return typeof val === 'object' ? (val.level ?? val.base ?? val.current ?? defaultValue) : val;
75	    }
76	    
77	    // Check by numeric ID (e.g. skills[1])
78	    if (id !== undefined) {
79	      val = skills[id];
80	      if (val !== undefined) {
81	        return typeof val === 'object' ? (val.level ?? val.base ?? val.current ?? defaultValue) : val;
82	      }
83	    }
84	    
85	    return defaultValue;
86	  }
87	
88	  public static calculateCombatLevel(skills: any): number {
89	    const attack = this.getSkillLevel(skills, 'attack', 1);
90	    const strength = this.getSkillLevel(skills, 'strength', 1);
91	    const defence = this.getSkillLevel(skills, 'defence', 1);
92	    const ranged = this.getSkillLevel(skills, 'ranged', 1);
93	    const magic = this.getSkillLevel(skills, 'magic', 1);
94	    const prayer = this.getSkillLevel(skills, 'prayer', 1);
95	    const constitution = this.getSkillLevel(skills, 'constitution', 10);
96	    
97	    const base = 0.25 * (defence + constitution + Math.floor(prayer / 2));
98	    const melee = 0.325 * (attack + strength);
99	    const range = 0.325 * (Math.floor(ranged / 2) + ranged);
100	    const mage = 0.325 * (Math.floor(magic / 2) + magic);
101	    
102	    return Math.floor(base + Math.max(melee, range, mage));
103	  }
104	}
