157	    private async checkOllama(): Promise<Omit<ServiceStatus, 'health'>> {
158	        if (!this.isRunning) return { id: 'ollama', name: 'Ollama Local', status: 'INACTIVE', type: 'API', details: 'Audit stopped' };
159	
160	        try {
161	            // Ping Ollama endpoint
162	            const response = await fetch('http://localhost:11434/api/tags');
163	            if (response.ok) {
164	                return { id: 'ollama', name: 'Ollama Local', status: 'ACTIVE', type: 'API' };
165	            }
166	            return { id: 'ollama', name: 'Ollama Local', status: 'INACTIVE', type: 'API', details: 'Service unreachable' };
167	        } catch {
168	            return { id: 'ollama', name: 'Ollama Local', status: 'INACTIVE', type: 'API' };
169	        }
170	    }
