172	    private async checkCloudExtensions(): Promise<Omit<ServiceStatus, 'health'>[]> {
173	        if (!this.isRunning) return [];
174	
175	        const extensions: Omit<ServiceStatus, 'health'>[] = [
176	            { id: 'healthcare', name: 'Bio Intelligence (MedGemma)', status: 'INACTIVE', type: 'EXTENSION' },
177	            { id: 'documentai', name: 'Document AI', status: 'INACTIVE', type: 'EXTENSION' },
178	            { id: 'vision', name: 'Cloud Vision', status: 'INACTIVE', type: 'EXTENSION' },
179	            { id: 'mediaforge', name: 'Media Forge (Imagen/Veo)', status: 'INACTIVE', type: 'EXTENSION' }
180	        ];
181	
182	        let deps: Record<string, string> = {};
183	        try {
184	            const pkgPath = join(this.config.projectRoot, 'package.json');
185	            if (fs.existsSync(pkgPath)) {
186	                const pkg = JSON.parse(fs.readFileSync(pkgPath, 'utf8'));
187	                deps = { ...pkg.dependencies, ...pkg.devDependencies };
188	            }
189	        } catch { }
190	
191	        const corePkgPath = join(coreRoot, 'package.json');
192	        let coreDeps: Record<string, string> = {};
193	        try {
194	            if (fs.existsSync(corePkgPath)) {
195	                const pkg = JSON.parse(fs.readFileSync(corePkgPath, 'utf8'));
196	                coreDeps = { ...pkg.dependencies, ...pkg.devDependencies };
197	            }
198	        } catch { }
199	
200	        const hasKey = !!process.env['GOOGLE_API_KEY'];
201	
202	        return extensions.map(ext => {
203	            const id = ext.id;
204	            const depKey = `@google-cloud/${id === 'healthcare' ? 'healthcare' : id === 'documentai' ? 'document-ai' : 'vision'}`;
205	            const isInstalled = !!deps[depKey] || !!coreDeps[depKey];
206	            const isAuthorized = this.isServiceAuthorized(id);
207	
208	            if (isAuthorized && hasKey) {
209	                return {
210	                    ...ext,
211	                    status: 'ACTIVE',
212	                    details: isInstalled ? 'Substrate: READY (Native)' : 'Substrate: READY (Cloud)'
213	                };
214	            }
215	
216	            if (isInstalled) {
217	                return { ...ext, status: 'ACTIVE', details: 'Installed (Wait for Authorization)' };
218	            }
219	
220	            return ext;
221	        });
222	    }
