262	    private async checkVSCodeExtension(): Promise<Omit<ServiceStatus, 'health'>> {
263	        if (!this.isRunning) return { id: 'extension', name: 'VS Code Bridge', status: 'INACTIVE', type: 'EXTENSION', details: 'Audit stopped' };
264	
265	        const wsPort = this.config.wsPort || 8765;
266	
267	        // Test WebSocket bridge availability by checking if the server is listening
268	        try {
269	            // Check if the WebSocket server is accepting connections
270	            const { createConnection } = await import('net');
271	            const isListening = await new Promise<boolean>((resolve) => {
272	                const socket = createConnection({ port: wsPort, host: 'localhost' }, () => {
273	                    socket.end();
274	                    resolve(true);
275	                });
276	                socket.on('error', () => resolve(false));
277	                socket.setTimeout(1000, () => {
278	                    socket.destroy();
279	                    resolve(false);
280	                });
281	            });
282	
283	            return {
284	                id: 'extension',
285	                name: 'VS Code Bridge',
286	                status: isListening ? 'ACTIVE' : 'INACTIVE',
287	                type: 'EXTENSION',
288	                details: isListening ? `WebSocket: ws://localhost:${wsPort} (READY)` : `Port ${wsPort} not listening`
289	            };
290	        } catch {
291	            return {
292	                id: 'extension',
293	                name: 'VS Code Bridge',
294	                status: 'INACTIVE',
295	                type: 'EXTENSION',
296	                details: 'Connection test failed'
297	            };
298	        }
299	    }
