301	    private async checkCloudflareWorker(): Promise<Omit<ServiceStatus, 'health'>> {
302	        if (!this.isRunning) return { id: 'worker', name: 'POG Sovereign Worker', status: 'INACTIVE', type: 'WORKER', details: 'Audit stopped' };
303	
304	        const workerUrl = process.env['CLOUDFLARE_WORKER_URL'];
305	
306	        // If worker URL is set, ping it to verify it's operational
307	        if (workerUrl) {
308	            try {
309	                const res = await fetch(workerUrl, { method: 'GET' });
310	                if (res.ok) {
311	                    const data = await res.json() as { service?: string; status?: string };
312	                    return {
313	                        id: 'worker',
314	                        name: 'POG Sovereign Worker',
315	                        status: 'ACTIVE',
316	                        type: 'WORKER',
317	                        details: `Substrate: ${data.service || 'Online'} (${data.status || 'Verified'})`
318	                    };
319	                }
320	                return {
321	                    id: 'worker',
322	                    name: 'POG Sovereign Worker',
323	                    status: 'ERROR',
324	                    type: 'WORKER',
325	                    details: `HTTP ${res.status}: ${res.statusText}`
326	                };
327	            } catch (err) {
328	                return {
329	                    id: 'worker',
330	                    name: 'POG Sovereign Worker',
331	                    status: 'ERROR',
332	                    type: 'WORKER',
333	                    details: `Unreachable: ${(err as Error).message}`
334	                };
335	            }
336	        }
337	
338	        // Fallback: Check API credentials if no URL is set
339	        const cf = new CloudflareServices({
340	            accountId: (process.env['CLOUDFLARE_ACCOUNT_ID'] || this.config.cloudflareAccountId),
341	            apiToken: (process.env['CLOUDFLARE_API_TOKEN'] || this.config.cloudflareApiToken)
342	        } as CloudflareConfig);
343	
344	        const audit = await cf.auditAbilities();
345	        const accountId = cf.getAccountId();
346	
347	        return {
348	            id: 'worker',
349	            name: 'POG Sovereign Worker',
350	            status: audit.ok ? 'ACTIVE' : (accountId ? 'ERROR' : 'INACTIVE'),
351	            type: 'WORKER',
352	            details: (audit.ok && audit.value)
353	                ? `Account: ${audit.value.accountId} (API Verified)`
354	                : (accountId ? `Token Error: ${audit.error?.message || 'Unknown verification error'}` : 'Missing worker substrate')
355	        };
356	    }
