429	    private async checkShellTools(): Promise<Array<Omit<ServiceStatus, 'health'>>> {
430	        if (!this.isRunning) return [];
431	
432	        const check = async (cmd: string, args: string[]): Promise<string | null> => {
433	            if (!this.isRunning) return null;
434	            try {
435	                const { spawn } = await import('child_process');
436	                return await new Promise<string | null>(resolve => {
437	                    const child = spawn(cmd, args, { shell: true });
438	                    let output = '';
439	                    child.stdout?.on('data', d => output += d.toString());
440	                    child.on('close', code => resolve(code === 0 ? output.trim() : null));
441	                    child.on('error', () => resolve(null));
442	                });
443	            } catch { return null; }
444	        };
445	
446	        const gitVersion = await check('git', ['--version']);
447	        const psVersion = await check('pwsh', ['-v']) || await check('powershell', ['-Command', '$PSVersionTable.PSVersion.ToString()']);
448	        const wranglerVersion = await check('wrangler', ['--version']);
449	        const gcloudVersion = await check('gcloud', ['--version']);
450	
451	        return [
452	            {
453	                id: 'tool_git',
454	                name: 'Git SCM',
455	                status: gitVersion ? 'ACTIVE' : 'INACTIVE',
456	                type: 'EXTENSION',
457	                details: gitVersion || 'Git binary not found in PATH'
458	            },
459	            {
460	                id: 'tool_powershell',
461	                name: 'PowerShell',
462	                status: psVersion ? 'ACTIVE' : 'INACTIVE',
463	                type: 'EXTENSION',
464	                details: psVersion ? `Version: ${psVersion}` : 'PowerShell not found'
465	            },
466	            {
467	                id: 'tool_wrangler',
468	                name: 'Wrangler CLI',
469	                status: wranglerVersion ? 'ACTIVE' : 'INACTIVE',
470	                type: 'EXTENSION',
471	                details: wranglerVersion ? `Version: ${wranglerVersion}` : 'Wrangler not found (Try `npm i -g wrangler`)'
472	            },
473	            {
474	                id: 'tool_gcloud',
475	                name: 'Google Cloud CLI',
476	                status: gcloudVersion ? 'ACTIVE' : 'INACTIVE',
477	                type: 'EXTENSION',
478	                details: gcloudVersion ? `Installed` : 'GCloud SDK not found'
479	            }
480	        ];
481	    }
